"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "The increased CPU limit should reduce throttling and allow the 'api' container to handle its workload without hitting the CPU limit.",
  "rationale": "The new version (4.2.0) uses more CPU than the previous version (4.1.3), as evidenced by higher CPU usage in revision 2's first 3h (88% of limit) compared to revision 1's 50%. The 'api' container is already using 99% of its 0.5 CPU limit and is throttled 60% of the time. Increasing the CPU limit to 750m should alleviate the throttling and allow the container to operate without hitting the limit.",
